/**
 * SteemAuth session protocol (v3 — the relay plane).
 *
 * QR payload (generated by the frontend app):
 * {
 *   "v": 3,                      // protocol version (v1/v2 QRs are refused)
 *   "t": "steem.session",        // payload type
 *   "sid": "<uuid>",             // unique session id
 *   "app": "SteemPro",           // requesting application name
 *   "url": "https://...",        // requesting application origin (display only)
 *   "src": "https://...",        // verified page origin (auto, non-overridable)
 *   "chain": "steem",            // target chain
 *   "rt": "wss://relay...",      // relay plane URL (the only endpoint)
 *   "rm": "rm_<base64url>",      // unguessable room (~176 bits)
 *   "tk": "tok_<base64url>",     // the PHONE's room token (app keeps its own)
 *   "k": "<base64-32bytes>",     // payload encryption key (both sides know it)
 *   "ts": 1712345678900,         // issued-at (ms)
 *   "exp": 1712345738900         // expiry (ms)
 * }
 *
 * All messages (including the `ready` handshake) ride the RELAY PLANE —
 * per-room sequenced logs with replay-on-join (steemauth-relay v3). Joins
 * authenticate with room tokens (the relay stores only sha256 hashes), and
 * every envelope is encrypt-then-MAC'd with keys derived from `k`, so the
 * relay can neither read messages nor inject one that verifies. Possession
 * of the QR (room + token + key) is the only capability; a leaked sid or
 * room name alone reveals nothing.
 */
import CryptoJS from 'crypto-js';

export const PROTOCOL_VERSION = 3;
/** Steem account names: 3-16 chars, lowercase, a-z / 0-9 / . / - (mirrors the package). */
const ACCOUNT_RE = /^[a-z][a-z0-9.-]{2,15}$/;
export const PAYLOAD_TYPE = 'steem.session';

/**
 * In-app browser handoff (mirrors @steempro/steemauth-qr's HANDOFF_TYPE —
 * the app never imports the package, it keeps its own protocol constants).
 *
 * When a page runs inside this app's own browser, it posts ONE message
 * through the WebView bridge instead of firing the steemauth:// OS intent:
 *     window.ReactNativeWebView.postMessage(
 *       JSON.stringify({ t: "steemauth.handoff", c: "<serializedQrPayload>" }))
 * That keeps the whole handoff in one process on one surface: no intent, no
 * route transit, nothing to flash. The `c` value is the same serialized QR
 * payload as a camera scan, so it goes through the identical parseSessionQr
 * validation (expiry, clock skew, relay endpoint, blocklist, target account).
 * Unknown messages are ignored.
 */
export const HANDOFF_TYPE = 'steemauth.handoff';

export interface SessionQrPayload {
  v: number;
  t: string;
  sid: string;
  app: string;
  url: string;
  chain: string;
  /**
   * Verified source origin — the page that generated the QR, captured
   * AUTOMATICALLY by the frontend package from `window.location.origin`.
   * It is deliberately not a package option: browsers mark Location
   * unforgeable, so page code cannot spoof it, and the phone displays it as
   * the app's real URL. Absent on QRs built outside a browser.
   */
  src?: string;
  /**
   * Relay plane URL (ws(s)://) BOTH sides join — the only endpoint anyone
   * needs. Never a credential: the same URL is already public in the QR.
   */
  rt: string;
  /** Unguessable room (~176 bits) — the relay's per-session stream. */
  rm: string;
  /**
   * The PHONE's room token. The requesting app keeps its OWN token out of
   * the QR; the relay stores only sha256 hashes of both.
   */
  tk: string;
  k: string;
  ts: number;
  exp: number;
  /**
   * Target account (optional): the Steem username this session expects.
   * When present the phone auto-selects it on connect - multi-account users
   * never have to switch by hand for a request to land on the right key.
   * Login QRs omit it (the scan establishes the account).
   */
  account?: string;
}

/**
 * The origin to show the user as "the app's URL": the verified `src` when the
 * frontend package captured it, otherwise the developer-declared `url`.
 */
export function appOrigin(payload: Pick<SessionQrPayload, 'src' | 'url'>): string {
  return payload.src ?? payload.url;
}

export type SessionMessage =
  /**
   * mobile → app: session established, account selected. (v3: the room
   * comes from the QR — no negotiation — the handshake itself travels as
   * a sealed row in the room log.)
   */
  | {
      type: 'ready';
      sid: string;
      account: string;
      authority: string;
      device?: string;
    }
  /** app → mobile: please execute/sign this request */
  | {
      type: 'request';
      sid: string;
      id: string;
      ops: unknown[];
      /** off-chain signing request — when set, `ops` is empty */
      sign?: SignRequest;
      action?: string;
      meta?: { description?: string; page?: string };
      /** ms timestamp after which the request is void */
      exp?: number;
    }
  /** mobile → app: result of a request */
  | {
      type: 'result';
      sid: string;
      id: string;
      ok: boolean;
      txId?: string;
      error?: string;
      account?: string;
      /** returned when the request only needed an off-chain signature */
      signature?: string;
    }
  /** app → mobile (or mobile → app): abandon a pending request */
  | { type: 'cancel'; sid: string; id: string; reason?: string }
  /**
   * mobile → app: the user revoked this app from the authenticator.
   * The whole session is over — the app must tear down its SteemAuthSession
   * and stop sending requests. Distinct from `cancel`, which only kills one
   * pending request.
   */
  | { type: 'revoke'; sid: string; reason?: string }
  /** keepalive */
  | { type: 'ping'; sid: string }
  | { type: 'pong'; sid: string };

export class ProtocolError extends Error {}

/**
 * Off-chain signing request.
 *
 * When present on a `request`, there is nothing to broadcast: the app shows
 * `data` verbatim, requires PIN/biometric approval, signs it with the
 * account's key and returns the compact signature in `result.signature`.
 * This is how a requesting site authenticates a user (Keychain-style
 * `requestSignBuffer`) without a private key ever leaving this device.
 */
export interface SignRequest {
  /** the exact UTF-8 text to sign — shown to the user exactly as sent */
  data: string;
  /** key to sign with; Posting for login, Active for privileged proofs */
  keyType?: string;
}

/** Generate a random session key (base64, 32 bytes). */
export function generateSessionKey(): string {
  const bytes = new Uint8Array(32);
  // crypto.getRandomValues is available in Hermes and browsers
  globalThis.crypto.getRandomValues(bytes);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}

export function generateSessionId(): string {
  if (typeof globalThis.crypto?.randomUUID === 'function') {
    return globalThis.crypto.randomUUID();
  }
  // Fallback: uuid-v4 from getRandomValues
  const b = new Uint8Array(16);
  globalThis.crypto.getRandomValues(b);
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  const hex = [...b].map((x) => x.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/** Parse + fully validate a scanned QR string. */
export function parseSessionQr(
  raw: string,
  options: { now?: number } = {},
): SessionQrPayload {
  const now = options.now ?? Date.now();
  let data: any;
  try {
    data = JSON.parse(raw.trim());
  } catch {
    throw new ProtocolError('Not a SteemAuth QR code (invalid JSON)');
  }
  if (!data || typeof data !== 'object') {
    throw new ProtocolError('Not a SteemAuth QR code');
  }
  if (data.t !== PAYLOAD_TYPE) {
    throw new ProtocolError('Unsupported QR code type');
  }
  if (data.v !== PROTOCOL_VERSION) {
    throw new ProtocolError(`Unsupported protocol version: ${data.v}`);
  }
  if (typeof data.sid !== 'string' || data.sid.length < 8) {
    throw new ProtocolError('QR code is missing a session id');
  }
  if (typeof data.k !== 'string' || data.k.length < 16) {
    throw new ProtocolError('QR code is missing its encryption key');
  }
  if (typeof data.exp !== 'number' || data.exp < now) {
    throw new ProtocolError('This QR code has expired — refresh it on the app');
  }
  if (typeof data.ts === 'number' && data.ts > now + 60_000) {
    throw new ProtocolError('QR code clock is in the future — check device time');
  }
  if (data.chain && data.chain !== 'steem') {
    throw new ProtocolError(`Unsupported chain: ${data.chain}`);
  }
  if (data.src !== undefined) {
    // Strict ORIGIN shape (mirrors createQrPayload's builder rule): host[:port]
    // only — no path, query, fragment, userinfo or whitespace. The old
    // prefix-only check accepted strings like https://trusted.example@evil.example
    // and https://trusted.example/anything, which the approval surfaces and the
    // blocklist would then render/enforce as a trusted identity.
    if (typeof data.src !== 'string' || !/^https?:\/\/(?:\[[^\]]+\]|[^/?#\s@]+)(?::\d+)?$/.test(data.src)) {
      throw new ProtocolError('QR code has an invalid app URL');
    }
  }
  // v3: the relay rendezvous fields are MANDATORY — without them there is
  // no room to join.
  if (typeof data.rt !== 'string' || !/^wss?:\/\//.test(data.rt)) {
    throw new ProtocolError('QR code is missing its relay URL (rt)');
  }
  if (typeof data.rm !== 'string' || !ROOM_RE.test(data.rm)) {
    throw new ProtocolError('QR code has an invalid room name (rm)');
  }
  if (typeof data.tk !== 'string' || !TOKEN_RE.test(data.tk)) {
    throw new ProtocolError('QR code has an invalid room token (tk)');
  }
  let account: string | undefined;
  if (data.account !== undefined) {
    const acc = typeof data.account === 'string' ? data.account.trim().toLowerCase() : '';
    if (!ACCOUNT_RE.test(acc)) {
      throw new ProtocolError('QR code has an invalid target account');
    }
    account = acc;
  }
  return {
    v: PROTOCOL_VERSION,
    t: PAYLOAD_TYPE,
    sid: data.sid,
    app: typeof data.app === 'string' ? data.app.slice(0, 80) : 'Unknown app',
    url: typeof data.url === 'string' ? data.url.slice(0, 200) : '',
    chain: 'steem',
    src: typeof data.src === 'string' ? data.src.slice(0, 200) : undefined,
    rt: data.rt.slice(0, 200),
    rm: data.rm,
    tk: data.tk,
    k: data.k,
    ts: typeof data.ts === 'number' ? data.ts : now,
    exp: data.exp,
    account,
  };
}

/** Format gates — byte-identical with the relay's rules. */
export const ROOM_RE = /^rm_[A-Za-z0-9_-]{16,64}$/;
export const TOKEN_RE = /^tok_[A-Za-z0-9_-]{32,128}$/;
const MAC_RE = /^[0-9a-f]{64}$/;

/** sha256 hex — used for room-token hashes and MAC-key derivation. */
export function sha256Hex(input: string): string {
  return CryptoJS.SHA256(input).toString();
}

/**
 * MAC key derived from the session key — domain-separated from the cipher's
 * own KDF so the two never share material. Both sides derive it identically.
 */
function macKeyFor(sessionKey: string): string {
  return CryptoJS.SHA256(`steemauth-v3-mac:${sessionKey}`).toString();
}

/** HMAC-SHA256 hex over `data` with the session's MAC key. */
export function hmacHex(data: string, sessionKey: string): string {
  return CryptoJS.HmacSHA256(data, macKeyFor(sessionKey)).toString();
}

/** Encrypt a protocol message for transport. */
export function encryptMessage(message: SessionMessage, key: string): string {
  return CryptoJS.AES.encrypt(JSON.stringify(message), key).toString();
}

/**
 * The v3 wire envelope: encrypt-then-MAC. The relay stores/forwards
 * `{ c, m }` blindly — it cannot read `c`, and any tampering (bit-flips,
 * swaps, injected rows) fails MAC verification and is dropped.
 */
export interface SealedEnvelope {
  c: string;
  m: string;
}

/** Seal a message into a relay-safe envelope. */
export function sealMessage(message: SessionMessage, key: string): SealedEnvelope {
  const c = encryptMessage(message, key);
  return { c, m: hmacHex(c, key) };
}

/**
 * Verify + open an envelope. Returns null for anything that fails MAC
 * verification or decryption — callers MUST treat null as "drop silently".
 */
export function openMessage(envelope: unknown, key: string): SessionMessage | null {
  if (!envelope || typeof envelope !== 'object') return null;
  const { c, m } = envelope as { c?: unknown; m?: unknown };
  if (typeof c !== 'string' || typeof m !== 'string' || !MAC_RE.test(m)) return null;
  const expected = hmacHex(c, key);
  let diff = 0;
  for (let i = 0; i < 64; i++) diff |= expected.charCodeAt(i) ^ m.charCodeAt(i);
  if (diff !== 0) return null;
  try {
    const bytes = CryptoJS.AES.decrypt(c, key);
    const text = bytes.toString(CryptoJS.enc.Utf8);
    if (!text) return null;
    const parsed = JSON.parse(text);
    if (!parsed || typeof parsed.type !== 'string') return null;
    return parsed as SessionMessage;
  } catch {
    return null;
  }
}

/** Decrypt a transport blob back into a protocol message. */
export function decryptMessage(cipher: string, key: string): SessionMessage {
  const bytes = CryptoJS.AES.decrypt(cipher, key);
  const text = bytes.toString(CryptoJS.enc.Utf8);
  if (!text) throw new ProtocolError('Failed to decrypt message (bad session key)');
  const parsed = JSON.parse(text);
  if (!parsed || typeof parsed.type !== 'string') {
    throw new ProtocolError('Malformed session message');
  }
  return parsed as SessionMessage;
}

/** Local sanity check on an inbound message (defense in depth). */
export function assertMessageForSession(
  message: SessionMessage,
  sid: string,
): void {
  if (message.sid !== sid) {
    throw new ProtocolError('Message for a different session');
  }
}
